import { prisma } from "../lib/prisma";
import { withRedisLock } from "./redisLock";

const EXPIRY_CHECK_INTERVAL_MS = 60 * 1000;

let intervalHandle: NodeJS.Timeout | null = null;

export function startInvoiceExpiryWorker(): void {
  if (intervalHandle) {
    return;
  }

  console.log("[InvoiceExpiry] Starting invoice expiry worker");

  // setInterval expects `() => void`; an `async` callback returns a
  // Promise that no caller awaits, so we wrap the async work in a
  // synchronous handler that swallows rejections (and logs them) to
  // satisfy `no-misused-promises`.
  intervalHandle = setInterval(() => {
    void (async () => {
      try {
        await withRedisLock('invoice_expiry', 50000, async () => {
          await expirePendingInvoices();
        });
      } catch (error) {
        console.error("[InvoiceExpiry] Error during expiry sweep:", error);
      }
    })();
  }, EXPIRY_CHECK_INTERVAL_MS);
}

export function stopInvoiceExpiryWorker(): void {
  if (intervalHandle) {
    clearInterval(intervalHandle);
    intervalHandle = null;
    console.log("[InvoiceExpiry] Stopped invoice expiry worker");
  }
}

// BE-C2 fix: transition expired invoices from pending to expired
async function expirePendingInvoices(): Promise<number> {
  const result = await prisma.invoice.updateMany({
    where: {
      status: "pending",
      expiresAt: {
        lt: new Date(),
      },
    },
    data: {
      status: "expired",
    },
  });

  if (result.count > 0) {
    console.log(`[InvoiceExpiry] Expired ${result.count} invoice(s)`);
  }

  return result.count;
}

import crypto, { timingSafeEqual } from 'crypto';

/**
 * Onramp.money Service
 * Handles quote generation, URL signing, and webhook verification.
 * 
 * Loopholes Addressed:
 * - Secure signing (no secrets in frontend)
 * - Order tracking (database persistence)
 * - Provider mapping (token/network normalization)
 */
export class OnrampService {
  private static readonly API_KEY = process.env.ONRAMP_MONEY_API_KEY || '';
  private static readonly API_SECRET = process.env.ONRAMP_MONEY_SECRET || '';
  private static readonly WIDGET_BASE_URL = 'https://onramp.money/main/buy/';

  /**
   * Generates a signed URL for the Onramp.money widget.
   * This pre-fills user data and ensures the request is authentic.
   */
  static generateSignedUrl(params: {
    userAddress: string;
    fiatAmount?: string;
    fiatCurrency?: string;
    cryptoToken?: string;
    network?: string;
    orderId?: string;
  }) {
    const {
      userAddress,
      fiatAmount,
      fiatCurrency = 'INR',
      cryptoToken = 'ETH',
      network = 'ethereum',
      orderId,
    } = params;

    const urlParams = new URLSearchParams({
      appId: this.API_KEY,
      walletAddress: userAddress,
      fiatAmount: fiatAmount || '',
      fiatType: fiatCurrency,
      coinCode: cryptoToken,
      network: network,
    });

    if (orderId) {
      urlParams.append('orderId', orderId);
      urlParams.append('partnerOrderId', orderId);
    }

    // Loophole Prevention: We will add a signature here if the provider requires it.
    // For Onramp.money, the appId is often enough for the basic widget, 
    // but a signature prevents tampering with the destination address.
    if (this.API_SECRET) {
      const signature = this.calculateSignature(urlParams.toString());
      urlParams.append('signature', signature);
    }

    return `${this.WIDGET_BASE_URL}?${urlParams.toString()}`;
  }

  /**
   * Verifies the HMAC-SHA256 signature from Onramp.money webhooks.
   */
  static verifyWebhook(payload: string, signature: string): boolean {
    if (!this.API_SECRET || !signature) return false;

    const hmac = crypto.createHmac('sha256', this.API_SECRET);
    const calculatedSignature = hmac.update(payload).digest('hex');

    if (signature.length !== calculatedSignature.length || !/^[0-9a-fA-F]+$/.test(signature)) {
      return false;
    }

    try {
      return timingSafeEqual(Buffer.from(signature, 'hex'), Buffer.from(calculatedSignature, 'hex'));
    } catch {
      return false;
    }
  }

  /**
   * Calculates signature for widget URL parameters.
   */
  private static calculateSignature(queryString: string): string {
    return crypto
      .createHmac('sha256', this.API_SECRET)
      .update(queryString)
      .digest('hex');
  }

  /**
   * Normalizes internal network keys to Onramp.money network names.
   */
  static mapNetwork(chainKey: string): string {
    const map: Record<string, string> = {
      'ethereum': 'ethereum',
      'polygon': 'polygon',
      'arbitrum': 'arbitrum',
      'base': 'base',
      'optimism': 'optimism',
      'bsc': 'bsc',
      'solana': 'solana',
    };
    return map[chainKey.toLowerCase()] || chainKey;
  }
}

import rateLimit, { type RateLimitRequestHandler } from "express-rate-limit";
import { prisma } from "../lib/prisma";
import { config } from "../config";
import { getRedisClient } from "../lib/redis";
import RedisStore from "rate-limit-redis";

function getStore(prefix: string) {
  const client = getRedisClient();
  if (!client) return undefined; // Fallback to memory store if Redis is unavailable
  // ioredis's `call(command, ...args)` returns `Promise<unknown>`. The
  // `RedisStore.sendCommand` contract is structurally compatible — the
  // store re-types the result internally — but the published types
  // declare a tighter `Promise<RedisReply>`. Bridge the gap with an
  // intermediate function typed as `Promise<unknown>` then re-typed
  // through `unknown` once at the call site to avoid an `any` value.
  const sendCommand = (...args: string[]): Promise<unknown> => {
    // `client.call` is typed as `Promise<unknown>` already, so no
    // assertion is required here.
    return client.call(args[0], ...args.slice(1));
  };
  return new RedisStore({
    // eslint-disable-next-line @typescript-eslint/no-explicit-any, @typescript-eslint/no-unsafe-assignment
    sendCommand: sendCommand as any,
    prefix: `rl:${prefix}:`,
  });
}

type CachedLimiterEntry = {
  limiter: RateLimitRequestHandler;
  expiresAt: number;
};

class MerchantLimiterCache {
  private readonly maxSize: number;
  private readonly ttlMs: number;
  private readonly entries = new Map<string, CachedLimiterEntry>();

  constructor(maxSize = 5000, ttlMs = 5 * 60 * 1000) {
    this.maxSize = maxSize;
    this.ttlMs = ttlMs;
  }

  get(merchantId: string): RateLimitRequestHandler | undefined {
    const entry = this.entries.get(merchantId);
    if (!entry) {
      return undefined;
    }

    if (Date.now() > entry.expiresAt) {
      this.entries.delete(merchantId);
      return undefined;
    }

    // Refresh LRU position on access.
    this.entries.delete(merchantId);
    this.entries.set(merchantId, entry);

    return entry.limiter;
  }

  set(merchantId: string, limiter: RateLimitRequestHandler): void {
    if (this.entries.has(merchantId)) {
      this.entries.delete(merchantId);
    }

    this.entries.set(merchantId, {
      limiter,
      expiresAt: Date.now() + this.ttlMs,
    });

    while (this.entries.size > this.maxSize) {
      const oldestKey = this.entries.keys().next().value;
      if (oldestKey === undefined) {
        break;
      }

      this.entries.delete(oldestKey);
    }
  }

  delete(merchantId: string): void {
    this.entries.delete(merchantId);
  }
}

const merchantLimiters = new MerchantLimiterCache();

const DEFAULT_LIMITS = {
  windowMs: 60 * 1000,
  max: 100,
};

const MERCHANT_LIMITS: Record<string, { windowMs: number; max: number }> = {
  basic: { windowMs: 60 * 1000, max: 60 },
  pro: { windowMs: 60 * 1000, max: 300 },
  enterprise: { windowMs: 60 * 1000, max: 1000 },
};

export function getMerchantTierLimit(tier: string): { windowMs: number; max: number } {
  return MERCHANT_LIMITS[tier] || DEFAULT_LIMITS;
}

export async function getMerchantLimiter(merchantId: string): Promise<RateLimitRequestHandler> {
  const cached = merchantLimiters.get(merchantId);
  if (cached) {
    return cached;
  }

  const merchant = await prisma.merchant.findUnique({
    where: { id: merchantId },
    select: { id: true, tier: true },
  });

  if (!merchant) {
    throw new Error(`Merchant not found: ${merchantId}`);
  }

  const tier = merchant.tier ?? config.defaultMerchantTier;
  const limits = getMerchantTierLimit(tier);

  const limiter = rateLimit({
    windowMs: limits.windowMs,
    max: limits.max,
    standardHeaders: true,
    legacyHeaders: false,
    store: getStore(`merchant:${merchantId}`),
    keyGenerator: () => merchantId,
    handler: (_req, res) => {
      res.status(429).json({
        error: "Rate limit exceeded",
        code: "RATE_LIMIT_EXCEEDED",
        retryAfter: Math.ceil(limits.windowMs / 1000),
      });
    },
  });

  merchantLimiters.set(merchantId, limiter);
  return limiter;
}

export function invalidateMerchantLimiter(merchantId: string): void {
  merchantLimiters.delete(merchantId);
}

export const globalRateLimiter = rateLimit({
  windowMs: 60 * 1000,
  max: 1000,
